AND NOT EXISTS (SELECT 1 FROM public.activities x WHERE x.skill_id = s.id AND x.prompt_text = 'Find the hidden bird!' AND x.card = '{"targets": [{"id": "o0", "label": "bird"}, {"id": "o2", "label": "kite"}, {"id": "o1", "label": "plane"}], "narration": "Find the hidden bird!"}'::jsonb AND x.answer = '{"choice": "o0"}'::jsonb);

